INSERT INTO `catalog_product_entity_text` VALUES
(3054,75,0,2173,'Apple iPhone 16 Plus la mau dien thoai chinh hang voi thiet ke hien dai, hieu nang on dinh va trai nghiem su dung muot ma. San pham phu hop cho nhu cau hoc tap, lam viec va giai tri hang ngay.'),
(3055,76,0,2173,'Apple iPhone 16 Plus la mau dien thoai chinh hang voi thiet ke hien dai, hieu nang on dinh va trai nghiem su dung muot ma. San pham phu hop cho nhu cau hoc tap, lam viec va giai tri hang ngay.'),
(3056,75,0,2174,'<p><strong>Apple iPhone 15 Pro</strong> là điện thoại chính hãng với thông số và mô tả được cập nhật đúng theo model thực tế.</p><ul><li>Tên sản phẩm: Apple iPhone 15 Pro</li><li>Mã SKU: BRAND-APPLE-02</li><li>Danh mục: Điện thoại chính hãng</li></ul><p>Phù hợp cho nhu cầu liên lạc, giải trí và làm việc hằng ngày với độ ổn định cao.</p>'),
(3057,76,0,2174,'<p>Apple iPhone 15 Pro là mẫu điện thoại chính hãng với thiết kế hiện đại, hiệu năng ổn định và trải nghiệm sử dụng mượt mà.</p>'),
